                 <input id="q1-html" name="q1" type="checkbox" value="html" data-correct="false">
                 <label for="q1-html">HTML</label>
               </li>
               <li class="option">
                 <input id="q1-cpp" name="q1" type="checkbox" value="cpp" data-correct="true">
                 <label for="q1-cpp">C++</label>
               </li>
               <li class="option">
                 <input id="q1-sql" name="q1" type="checkbox" value="sql" data-correct="false">
