                 <input id="q2-rust" name="q2" type="checkbox" value="rust" data-correct="true">
                 <label for="q2-rust">Rust</label>
               </li>
               <li class="option">
                 <input id="q2-go" name="q2" type="checkbox" value="go" data-correct="true">
