   <script>
     const form = document.querySelector('#quiz');
     const status = document.querySelector('#status');
     const results = document.querySelector('#results');
     const score = document.querySelector('#score');
     const breakdown = document.querySelector('#breakdown');

     const questions = [
       {
         title: 'Question 1',
         inputs: [...document.querySelectorAll('input[name="q1"]')],
       },
       {
         title: 'Question 2',
         inputs: [...document.querySelectorAll('input[name="q2"]')],
       },
       {
         title: 'Question 3',
         inputs: [...document.querySelectorAll('input[name="q3"]')],
       },
     ];

     const formatAnswerList = (inputs) =>
       inputs
         .filter((input) => input.dataset.correct === 'true')
         .map((input) => input.nextElementSibling.textContent)
         .join(', ');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       let correctCount = 0;
       const lines = [];

       questions.forEach((question) => {
         const selected = question.inputs.filter((input) => input.checked);
         const correct = question.inputs.filter((input) => input.dataset.correct === 'true');
         const isCorrect =
           selected.length === correct.length &&
           selected.every((input) => input.dataset.correct === 'true');

         if (isCorrect) {
           correctCount += 1;
         }

         lines.push({
           title: question.title,
           message: isCorrect
             ? 'Correct.'
             : `Incorrect. Correct answers: ${formatAnswerList(question.inputs)}.`,
           className: isCorrect ? 'correct' : 'incorrect',
         });
       });

       score.textContent = `You got ${correctCount} out of ${questions.length} correct.`;
       breakdown.replaceChildren(
         ...lines.map(({ title, message, className }) => {
           const item = document.createElement('li');
           item.className = className;
           item.textContent = `${title}: ${message}`;
           return item;
         })
       );

       results.hidden = false;
       status.textContent = 'Quiz submitted.';
       results.focus();
     });
   </script>
